#!/usr/bin/env bash
# Flash the RoboDog ESP-Claw (edge_agent) firmware to the Waveshare ESP32-S3
# RLCD, button-free, and provision the esp-claw `app` NVS namespace (Wi-Fi +
# OpenAI-style LLM endpoint) so the board boots straight onto the LAN.
#
# IMPORTANT: this runs esptool on the HOST (Docker ttyACM RTS passthrough
# breaks the button-free reset) — the same sanctioned esptool path as
# robodog_client/flash.sh for this board.  Requires host `python3 -m esptool`.
#
# The NVS image is generated by the IDF Docker image's nvs_partition_gen.py
# (mirrors the calendar --kid-name flow) and written at 0xA000 (24 KB NVS
# partition of the edge_agent partitions_16MB.csv table).  Writing it WIPES the
# whole NVS partition each flash — the app's runtime config is rebuilt here, so
# that is the intended provisioning step.  Pass --no-nvs to leave NVS as-is.
#
# Credentials/endpoints come from the environment (or local_secrets.h), never
# are committed:
#   FLASH_PORT, FLASH_BAUD            (defaults /dev/ttyACM0, 460800)
#   CLAW_WIFI_SSID / CLAW_WIFI_PASSWORD (default: robodog_client/main/local_secrets.h)
#   CLAW_LLM_BASE_URL                 (default http://gx10-f156:8000/v1)
#   CLAW_LLM_MODEL                    (default deepseek-ai/DeepSeek-V4-Flash-0731)
#
#   bazel run //robodog_client:flash_robodog_claw [-- --port /dev/ttyACM0]
set -euo pipefail
if [ -n "${BUILD_WORKSPACE_DIRECTORY:-}" ]; then
    APP="$BUILD_WORKSPACE_DIRECTORY/robodog_client"
else
    APP="$(cd "$(dirname "$0")/.." && pwd)"
fi
PORT="${FLASH_PORT:-/dev/ttyACM0}"
BAUD="${FLASH_BAUD:-460800}"
IDF_IMG="${CLAW_IDF_IMG:-espressif/idf:v5.5.4}"
NVS=1
while [ $# -gt 0 ]; do
    case "$1" in
        --port)
            if [ $# -lt 2 ] || [[ "$2" == -* ]]; then
                echo "error: --port requires a value (default: /dev/ttyACM0)" >&2
                exit 2
            fi
            PORT="$2"; shift 2;;
        --no-nvs)
            NVS=0; shift;;
        *)
            echo "unknown argument: $1 (expected --port <port>, --no-nvs)" >&2
            exit 2;;
    esac
done
if ! python3 -c "import esptool" >/dev/null 2>&1; then
    echo "host esptool is required (button-free reset can't run in Docker):" >&2
    echo "  python3 -m pip install esptool" >&2
    exit 1
fi

BUILD="$APP/.esp-claw/application/edge_agent/build"
if [ ! -f "$BUILD/flash_args" ]; then
    echo "no $BUILD/flash_args — run //robodog_client:build_robodog_claw first" >&2
    exit 1
fi

# ── provision the esp-claw `app` NVS namespace ──────────────────────────────
NVS_WORK=""
cleanup() { [ -n "$NVS_WORK" ] && [ -d "$NVS_WORK" ] && rm -rf "$NVS_WORK"; }
trap cleanup EXIT
NVS_ARGS=()

if [ "$NVS" -eq 1 ]; then
    SECRETS="$APP/main/local_secrets.h"
    WIFI_SSID="${CLAW_WIFI_SSID:-}"
    WIFI_PASS="${CLAW_WIFI_PASSWORD:-}"
    if [ -z "$WIFI_SSID" ] && [ -f "$SECRETS" ]; then
        WIFI_SSID=$(sed -n 's/.*RD_WIFI_SSID_DEFAULT[[:space:]]*"\([^"]*\)".*/\1/p' "$SECRETS" | head -1 || true)
    fi
    if [ -z "$WIFI_PASS" ] && [ -f "$SECRETS" ]; then
        WIFI_PASS=$(sed -n 's/.*RD_WIFI_PASS_DEFAULT[[:space:]]*"\([^"]*\)".*/\1/p' "$SECRETS" | head -1 || true)
    fi
    if [ -z "$WIFI_SSID" ]; then
        echo "error: no CLAW_WIFI_SSID and no local_secrets.h default found" >&2
        exit 1
    fi
    LLM_BASE="${CLAW_LLM_BASE_URL:-http://gx10-f156:8000/v1}"
    LLM_MODEL="${CLAW_LLM_MODEL:-deepseek-ai/DeepSeek-V4-Flash-0731}"

    NVS_WORK="$(mktemp -d /tmp/robodog_claw_nvs.XXXXXX)"
    # cfg_ver must match the app's APP_CONFIG_SCHEMA_VERSION ("1") or
    # app_config_init() erases the whole `app` namespace on first boot
    # (wiping the keys we just wrote) to re-seed a clean schema.
    cat > "$NVS_WORK/app_nvs.csv" <<EOF
key,type,encoding,value
app,namespace,,
cfg_ver,data,string,1
wifi_ssid,data,string,$WIFI_SSID
wifi_password,data,string,$WIFI_PASS
llm_backend,data,string,openai_compatible
llm_endpoint,data,string,static
llm_base_url,data,string,$LLM_BASE
llm_model,data,string,$LLM_MODEL
llm_auth_type,data,string,none
llm_sup_tools,data,string,true
llm_sup_vis,data,string,false
EOF
    echo "generating esp-claw NVS image (app namespace, 24 KB) via IDF nvs_partition_gen.py"
    docker run --rm \
        -v "$APP:/workspace" -w /workspace \
        -v "$NVS_WORK:/nvs" \
        "$IDF_IMG" \
        python3 /opt/esp/idf/components/nvs_flash/nvs_partition_generator/nvs_partition_gen.py \
            generate /nvs/app_nvs.csv /nvs/nvs.bin 0x6000 >/dev/null
    NVS_ARGS=(0xA000 "$NVS_WORK/nvs.bin")
    echo "board $PORT: Wi-Fi ssid='$WIFI_SSID' LLM=$LLM_MODEL @ $LLM_BASE"
fi

cd "$BUILD"
echo "flashing esp-claw edge_agent from @flash_args ..."
python3 -m esptool --chip esp32s3 -p "$PORT" -b "$BAUD" \
    --before default_reset --after hard_reset write_flash \
    @flash_args "${NVS_ARGS[@]}"
if [ "$NVS" -eq 1 ]; then
    echo "==== board $PORT flashed + NVS provisioned (app namespace @ 0xA000) ===="
else
    echo "==== board $PORT flashed (NVS untouched) ===="
fi
